const I=(name,cls='')=>`<span class="icon ${cls}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.info}</svg></span>`;
const state={screen:'wall',filter:'全部',myFilter:'全部',activityFilter:'全部',course:'高等数学',purpose:'期中期末冲刺',basis:'概念还没弄懂',reduced:false,solid:false};
try{state.reduced=localStorage.getItem('campus-prototype-reduced')==='true';state.solid=localStorage.getItem('campus-prototype-solid')==='true'}catch(e){}
const screens=[['wall','01 校园墙'],['resources','02 学习资料'],['ai','03 AI 帮我挑笔记'],['activities','04 找搭子'],['my','05 我的'],['compose','06 发布文字帖'],['detail','07 帖子详情'],['mine','08 我的帖子'],['access','09 申请内测'],['access-pending','10 等待审批'],['access-denied','11 申请未通过'],['access-revoked','12 资格已撤销'],['review','13 审核队列'],['review-detail','14 审核详情'],['members','15 内测成员'],['settings','16 设置与帮助'],['empty','17 空列表'],['loading','18 加载中'],['error','19 加载失败'],['compose-error','20 发布失败'],['compose-pending','21 发布中'],['published','22 发布成功'],['submitted','23 提交待审'],['rejected','24 驳回详情'],['hidden','25 内容已下架'],['deleted','26 内容已删除'],['delete-confirm','27 删除确认'],['leave-confirm','28 离开确认'],['review-confirm','29 审核确认'],['review-processed','30 已被处理'],['pagination','31 加载下一页'],['demo-unavailable','32 演示操作说明'],['ai-result','33 演示推荐结果'],['members-approved','34 成员批准结果'],['member-revoke','35 撤销资格确认'],['settings-solid','36 减少透明度']];
const annotations={wall:['四分区筛选；时间倒序，保留已加载内容。','真实校园墙不注入示例数据。原型样例仅用于视觉。','搜索、图片、点赞评论首轮尚未开放。'],resources:['资料与价格均为演示内容。','试读、购买、上传入口说明尚未开放。','AI 入口进入点选推荐演示。'],ai:['所有选项有明确选中状态。','输出推荐理由与三条适配说明，不评分。'],activities:['以比赛或活动为起点找人。','首轮不创建真实申请，不公开联系方式。'],my:['显示真实内测资格，不称实名认证。','管理员专属入口由服务端权限决定。'],compose:['标题 60 字，正文 2000 字。','错误保留输入；提交中锁定，超时重试复用请求号。','有输入时离开需确认。'],detail:['正文完整阅读，作者随时删除。','无权限、下架、删除均有独立状态。'],review:['仅管理员可访问。','待审、驳回、下架留审计记录。'],members:['仅管理员审批或撤销内测资格。','资格撤销后服务端立即拒绝读写。']};
function btn(label,to,type='primary',icon=''){return `<button class="${type}" ${to?`data-go="${to}"`:''}>${icon?I(icon):''}${label}</button>`}
function hero(title,sub,icon='wall',small=false){return `<section class="hero ${small?'small':''}"><div class="brand">${I(icon)}校园回声</div><h1>${title}</h1><p>${sub}</p></section>`}
function notice(txt,kind=''){return `<div class="notice ${kind}">${txt}</div>`}
function tag(txt,kind=''){return `<span class="tag ${kind}">${txt}</span>`}
function avatar(letter='林',kind=''){return `<div class="avatar ${kind}">${letter}</div>`}
function post(title,content,letter='林',category='学习互助',status=''){return `<article class="card"><div class="meta">${avatar(letter)}<div><div class="name">${letter}同学</div><div class="sub">11 月 11 日 · 10:24</div></div><div style="margin-left:auto">${status?tag(status,status==='待审核'?'pending':''):tag(category)}</div></div><h3>${title}</h3><p>${content}</p><div class="post-footer"><span class="sub">校园回声 · 文字帖</span><button class="text-btn" data-go="detail">查看全文${I('next')}</button></div></article>`}
function tab(active){return `<nav class="tabs" aria-label="主导航">${[['wall','wall','校园墙'],['resources','book','学习资料'],['activities','users','找搭子'],['my','user','我的']].map(([key,icon,label])=>`<button class="tab ${active===key?'active':''}" data-go="${key}" ${active===key?'aria-current="page"':''}>${I(icon)}${label}</button>`).join('')}</nav>`}
function native(title,back){return `<div class="status"><span>9:41</span><span>▮▮▮ &nbsp; Wi-Fi &nbsp; ▰</span></div><header class="native">${back?`<button class="back" data-go="${back}" aria-label="返回">${I('back')}</button>`:''}<span>${title}</span><div class="capsule" aria-hidden="true">···<span></span>⊙</div></header>`}
function link(label,to,icon='file',badge=''){return `<button class="list-link" data-go="${to}">${I(icon)}<span>${label}</span>${badge?`<span class="badge-count">${badge}</span>`:''}${I('next','next')}</button>`}
const formText='图书馆二楼靠窗的位置终于等到了好天气。想约周四下午一起复习高数的同学，带上笔记，一起把易错点过一遍。';
function composer(mode=''){return `<div class="content"><div class="notice">目前仅支持文字帖。图片、匿名、评论与点赞将在后续开放。</div><label class="label" for="category">选择分区 <span class="required">*</span></label><select id="category" class="select"><option>学习互助</option><option>失物招领</option><option>吐槽树洞</option><option>闲置转让</option></select><label class="label" for="title">标题 <span class="required">*</span></label><input id="title" class="input" maxlength="60" placeholder="一句话说清你想分享的事" value="${mode?'周四下午，图书馆一起复习高数吗？':''}"><div class="field-hint"><span>清晰的标题更容易被同学看到</span><span id="title-count">${mode?'18':'0'} / 60</span></div><label class="label" for="body">正文 <span class="required">*</span></label><textarea id="body" class="textarea" maxlength="2000" placeholder="说说发生了什么，或你需要什么帮助">${mode?formText:''}</textarea><div class="field-hint"><span>不发布个人敏感信息和违规内容</span><span id="body-count">${mode?'70':'0'} / 2000</span></div>${mode==='error'?'<div class="field-error">内容审核暂不可用，输入已保留。稍后可原样重试。</div>':''}<div class="rule"></div><div class="help-copy">发布后先经过内容审核。需要人工复核的帖子会显示“待审核”，审核通过后才会出现在校园墙。</div></div>`}
function stateView(icon,title,copy,buttons=''){return `<div class="content"><div class="state"><div class="symbol">${I(icon)}</div><h2>${title}</h2><p>${copy}</p>${buttons}</div></div>`}
function modal(title,copy,actions,center=true){return `<div class="sheet-backdrop"><section class="dialog ${center?'center':''}" role="dialog" aria-modal="true" aria-label="${title}"><h2>${title}</h2><p>${copy}</p><div class="dialog-actions">${actions}</div></section></div>`}
