let navigationTimer;
function go(s){
 clearTimeout(navigationTimer);
 const dialog=document.querySelector('.dialog');
 const commit=()=>{if(s==='settings-solid')state.solid=true;state.screen=s;history.replaceState(null,'','#'+s);render()};
 if(dialog&&!state.reduced){dialog.classList.remove('is-open');navigationTimer=setTimeout(commit,160)}else commit();
}
function bind(){document.querySelectorAll('[data-go]:not([data-decision])').forEach(el=>el.addEventListener('click',()=>go(el.dataset.go)));document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{state.filter=el.dataset.filter;state.screen='wall';render()});document.querySelectorAll('[data-my-filter]').forEach(el=>el.onclick=()=>{state.myFilter=el.dataset.myFilter;render()});document.querySelectorAll('[data-activity]').forEach(el=>el.onclick=()=>{state.activityFilter=el.dataset.activity;render()});document.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>{state[el.dataset.choice]=el.dataset.value;render()});const red=document.querySelector('#reduced');if(red)red.onclick=()=>{state.reduced=!state.reduced;try{localStorage.setItem('campus-prototype-reduced',String(state.reduced))}catch(e){}render()};const solid=document.querySelector('#solid');if(solid)solid.onclick=()=>{state.solid=!state.solid;try{localStorage.setItem('campus-prototype-solid',String(state.solid))}catch(e){}render()};const filter=document.querySelector('#filter-btn');if(filter)filter.onclick=()=>{const p=document.querySelector('.pill-scroll');p.scrollIntoView({block:'nearest',behavior:state.reduced?'instant':'smooth'})};const ti=document.querySelector('#title'),bo=document.querySelector('#body');if(ti)ti.oninput=()=>document.querySelector('#title-count').textContent=ti.value.length+' / 60';if(bo)bo.oninput=()=>document.querySelector('#body-count').textContent=bo.value.length+' / 2000';}
const query=new URLSearchParams(location.search);if(query.has('snapshot'))document.body.classList.add('app-snapshot');state.screen=location.hash.slice(1)||query.get('screen')||'wall';if(state.screen==='settings-solid')state.solid=true;render();window.prototype={go,state,screens};
window.addEventListener('hashchange',()=>{state.screen=location.hash.slice(1)||'wall';render()});

function enhance(){
 const title=document.querySelector('#title'),body=document.querySelector('#body');
 if(title&&body){
  let saved={};try{saved=JSON.parse(localStorage.getItem('campus-echo-prototype-draft')||'{}')}catch(e){}
  if(state.screen==='compose'){title.value=saved.title||'';body.value=saved.body||''}
  const update=()=>{localStorage.setItem('campus-echo-prototype-draft',JSON.stringify({title:title.value,body:body.value}));document.querySelector('#title-count').textContent=title.value.length+' / 60';document.querySelector('#body-count').textContent=body.value.length+' / 2000'};
  title.oninput=update;body.oninput=update;document.querySelector('#title-count').textContent=title.value.length+' / 60';document.querySelector('#body-count').textContent=body.value.length+' / 2000';
 }
 const pub=document.querySelector('[data-act="publish"]');if(pub)pub.onclick=()=>{const ti=document.querySelector('#title'),bo=document.querySelector('#body');if(!ti.value.trim()||!bo.value.trim()){let err=document.querySelector('#local-error');if(!err){err=document.createElement('div');err.id='local-error';err.className='field-error';bo.insertAdjacentElement('afterend',err)}err.textContent='请填写标题和正文。输入会保留。';(!ti.value.trim()?ti:bo).focus();return}localStorage.setItem('campus-echo-prototype-draft',JSON.stringify({title:ti.value,body:bo.value}));go('compose-pending');setTimeout(()=>go('submitted'),650)};
 const apply=document.querySelector('[data-act="apply"]');if(apply)apply.onclick=()=>{const nick=document.querySelector('#nickname'),reason=document.querySelector('#reason'),terms=document.querySelector('#terms');if(!nick.value.trim()||!reason.value.trim()||!terms.checked){let err=document.querySelector('#apply-error');if(!err){err=document.createElement('div');err.id='apply-error';err.className='field-error';apply.insertAdjacentElement('beforebegin',err)}err.textContent='请填写昵称、申请说明，并阅读勾选内测规则。';return}go('access-pending')};
 document.querySelectorAll('[data-decision]').forEach(el=>{el.onclick=()=>{const reason=document.querySelector('#review-reason');if(el.dataset.decision==='reject'&&!reason.value.trim()){let err=document.querySelector('#review-error');if(!err){err=document.createElement('div');err.id='review-error';err.className='field-error';reason.insertAdjacentElement('afterend',err)}err.textContent='请填写驳回原因，便于作者理解和修改。';reason.focus();return}state.decision=el.dataset.decision;go('review-confirm')}});
}
